ture\",null,{\"children\":\"$3d\"}]}]}]]}]\n"])self.__next_f.push([1,"33:[\"$\",\"em\",null,{\"children\":\"arjuna\"}]\n34:[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"O Arjuna\"}}]\n36:[\"$\",\"$L2b\",\"child-451\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:5\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base text-center italic\",\"dangerouslySetInnerHTML\":{\"__html\":\"īśvaraḥ paramaḥ kṛṣṇaḥ
sac-cid-ānanda-vigrahaḥ
anādir ādir govindaḥ
sarva-kāraṇa-kāraṇam\"}}]}]\n37:[\"$\",\"$L2b\",\"child-452\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:6\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"children\":[\"“There are many personalities possessing the qualities of Bhagavān, but Kṛṣṇa is the supreme because none can excel Him. He is the Supreme Person, and His body is eternal, full of knowledge and bliss. He is the primeval Lord Govinda and the cause of all causes.” (\",[\"$\",\"$L20\",\"1\",{\"href\":\"/en/library/bs/5/1/\",\"children\":[[\"$\",\"em\",\"0\",{\"children\":\"Brahma-saṁhitā\"}],\" 5.1\"]}],\")\"]}]}]\n38:[\"$\",\"$L2b\",\"child-453\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:7\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"In the Bhāgavatam also there is a list of many incarnations of the Supreme Personality of Godhead, but Kṛṣṇa is described as the original Personality of Godhead, from whom many, many incarnations and Personalities of Godhead expand:\"}}]}]\n39:[\"$\",\"$L2b\",\"child-454\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:8\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base text-center italic\",\"dangerouslySetInnerHTML\":{\"__html\":\"ete cāṁśa-kalāḥ puṁsaḥ
kṛṣṇas tu bhagavān svayam
indrāri-vyākulaṁ lokaṁ
mṛḍayanti yuge yuge\"}}]}]\n3a:[\"$\",\"$L2b\",\"child-455\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:9\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"children\":[\"“All the lists of the incarnations of Godhead submitted herewith are either plenary expansions or parts of the plenary expansions of the Supreme Godhead, but Kṛṣṇa is the Supreme Personality of Godhead Himself.” (\",[\"$\",\"$L20\",\"1\",{\"href\":\"/en/library/sb/1/3/28/\",\"children\":[[\"$\",\"em\",\"0\",{\"children\":\"Bhāg.\"}],\" 1.3.28\"]}],\")\"]}]}]\n3b:[\"$\",\"$L2b\",\"child-456\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:10\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"Therefore, Kṛṣṇa is the original Supreme Personality of Godhead, the Absolute Truth, the source of both the Supersoul and the impersonal Brahman.\"}}]}]\n3e:T4d4,In the presence of the Supreme Personality of Godhead, Arjuna’s lamentation for his kinsmen is certainly unbecoming, and therefore Kṛṣṇa expressed His surprise with the word kutaḥ, “wherefrom.” Such impurities were never expected from a person belonging to the civilized class of men known as Āryans. The word āryan is applicable to persons who know the value of life and have a civilization based on spiritual realization. Persons who are led by the material conception of life do not know that the aim of life is realization of the Absolute Truth, Viṣṇu, or Bhagavān, and they are captivated by the external features of the material world, and therefore they do not know what liberation is. Persons who have no knowledge of liberation from material bondage are called non-Āryans. Although Arjuna was a kṣatriya, he was deviating from his prescribed duties by declining to fight. This act of cowardice is described as befitting the non-Āryans. Such deviation from duty does not help one in the progr"])self.__next_f.push([1,"ess of spiritual life, nor does it even give one the opportunity to become famous in this world. Lord Kṛṣṇa did not approve of the so-called compassion of Arjuna for his kinsmen.3c:[\"$\",\"$L2b\",\"child-457\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:11\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"$3e\"}}]}]\n"])(function(){function c(){var b=a.contentDocument||(a.contentWindow&&a.contentWindow.document);if(b){var d=b.createElement(''script'');d.innerHTML="window.__CF$cv$params={r:''a34054c08b54f501'',t:''MTc4ODIyNDM1Mw==''};var a=document.createElement(''script'');a.src=''/cdn-cgi/challenge-platform/scripts/jsd/main.js'';document.getElementsByTagName(''head'')[0].appendChild(a);";b.getElementsByTagName(''head'')[0].appendChild(d)}}if(document.body){var a=document.createElement(''iframe'');a.height=1;a.width=1;a.style.position=''absolute'';a.style.top=0;a.style.left=0;a.style.border=''none'';a.style.visibility=''hidden'';document.body.appendChild(a);if(''loading''!==document.readyState)c();else if(window.addEventListener)document.addEventListener(''DOMContentLoaded'',c);else{var e=document.onreadystatechange||function(){};document.onreadystatechange=function(b){e(b);''loading''!==document.readyState&&(document.onreadystatechange=e,c())}}}})();', 'https://vedabase.io/en/library/bg/2/2/', true),
(2, '3', 3, 'class="av-devanagari">क्ल‍ैब्यं मा स्म गमः पार्थ नैतत्त्वय्युपपद्यते ।
क्षुद्रं हृदयदौर्बल्यं त्यक्त्वोत्तिष्ठ परन्तप ॥ ३ ॥

<div', 'class="av-verse_text">klaibyaṁ mā sma gamaḥ pārtha
naitat tvayy upapadyate
kṣudraṁ hṛdaya-daurbalyaṁ
tyaktvottiṣṭha paran-tapa

<div', 'class="av-synonyms">klaibyam — impotence; mā sma — do not; gamaḥ — take to; pārtha — O son of Pṛthā; na — never; etat — this; tvayi — unto you; upapadyate — is befitting; kṣudram — petty; hṛdaya — of the heart; daurbalyam — weakness; tyaktvā — giving up; uttiṣṭha — get up; param-tapa — O chastiser of the enemies.

<div', 'class="av-translation">O son of Pṛthā, do not yield to this degrading impotence. It does not become you. Give up such petty weakness of heart and arise, O chastiser of the enemy.

<div', 'class="av-purport">Arjuna was addressed as the son of Pṛthā, who happened to be the sister of Kṛṣṇa’s father Vasudeva. Therefore Arjuna had a blood relationship with Kṛṣṇa. If the son of a kṣatriya declines to fight, he is a kṣatriya in name only, and if the son of a brāhmaṇa acts impiously, he is a brāhmaṇa in name only. Such kṣatriyas and brāhmaṇas are unworthy sons of their fathers; therefore, Kṛṣṇa did not want Arjuna to become an unworthy son of a kṣatriya. Arjuna was the most intimate friend of Kṛṣṇa, and Kṛṣṇa was directly guiding him on the chariot; but in spite of all these credits, if Arjuna abandoned the battle he would be committing an infamous act. Therefore Kṛṣṇa said that such an attitude in Arjuna did not fit his personality. Arjuna might argue that he would give up the battle on the grounds of his magnanimous attitude for the most respectable Bhīṣma and his relatives, but Kṛṣṇa considered that sort of magnanimity mere weakness of heart. Such false magnanimity was not approved by any authority. Therefore, such magnanimity or so-called nonviolence should be given up by persons like Arjuna under the direct guidance of Kṛṣṇa.

