यद्वा जयेम यदि वा नो जयेयुः ।
यानेव हत्वा न जिजीविषाम-
स्तेऽवस्थिताः प्रमुखे धार्तराष्ट्राः ॥ ६ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":478,\"bb\":436,\"url_path\":\"/en/library/bg/2/6/b436/\",\"body_value\":\"na caitad vidmaḥ kataran no garīyo
yad vā jayema yadi vā no jayeyuḥ
yān eva hatvā na jijīviṣāmas
te ’vasthitāḥ pramukhe dhārtarāṣṭrāḥ\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":479,\"bb\":437,\"url_path\":\"/en/library/bg/2/6/b437/\",\"shadow_value\":\"na – nor; ca – also; etat – this; vidmaḥ – do we know; katarat – which; naḥ – for us; garīyaḥ – better; yat vā – whether; jayema – we may conquer; yadi – if; vā – or; naḥ – us; jayeyuḥ – they conquer; yān – those who; eva – certainly; hatvā – by killing; na – never; jijīviṣāmaḥ – we would want to live; te – all of them; avasthitāḥ – are situated; pramukhe – in the front; dhārtarāṣṭrāḥ – the sons of Dhṛtarāṣṭra.\",\"word_for_word_value\":[{\"word\":\"na\",\"translation\":\"nor\"},{\"word\":\"ca\",\"translation\":\"also\"},{\"word\":\"etat\",\"translation\":\"this\"},{\"word\":\"vidmaḥ\",\"translation\":\"do we know\"},{\"word\":\"katarat\",\"translation\":\"which\"},{\"word\":\"naḥ\",\"translation\":\"for us\"},{\"word\":\"garīyaḥ\",\"translation\":\"better\"},{\"word\":\"yat vā\",\"translation\":\"whether\"},{\"word\":\"jayema\",\"translation\":\"we may conquer\"},{\"word\":\"yadi\",\"translation\":\"if\"},{\"word\":\"vā\",\"translation\":\"or\"},{\"word\":\"naḥ\",\"translation\":\"us\"},{\"word\":\"jayeyuḥ\",\"translation\":\"they conquer\"},{\"word\":\"yān\",\"translation\":\"those who\"},{\"word\":\"eva\",\"translation\":\"certainly\"},{\"word\":\"hatvā\",\"translation\":\"by killing\"},{\"word\":\"na\",\"translation\":\"never\"},{\"word\":\"jijīviṣāmaḥ\",\"translation\":\"we would want to live\"},{\"word\":\"te\",\"translation\":\"all of them\"},{\"word\":\"avasthitāḥ\",\"translation\":\"are situated\"},{\"word\":\"pramukhe\",\"translation\":\"in the front\"},{\"word\":\"dhārtarāṣṭrāḥ\",\"translation\":\"the sons of Dhṛtarāṣṭra\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":480,\"bb\":438,\"url_pat